import('playwright-core').then(async pw => {
  const fs = await import('node:fs');
  const path = await import('node:path');
  const { pathToFileURL } = await import('node:url');
  const chrome = '/Users/orca/Library/Caches/ms-playwright';
  const dir = fs.readdirSync(chrome).filter(d=>d.startsWith('chromium')).sort().reverse()[0];
  const exe = path.join(chrome, dir, 'chrome-mac', 'headless_shell');
  const game = pathToFileURL('/Users/orca/ai/otter-buddy/.otter/worktrees/kelp-farm-p1/game/index.html').href;
  const b = await pw.chromium.launch({ executablePath: exe });
  const p = await b.newPage();
  const errs = [];
  p.on('pageerror', e => errs.push('pageerror: '+e.message));
  await p.goto(game);
  await p.waitForTimeout(300);

  async function flow(autoMerge) {
    const r = { diverge:null, postAdvance:null, errs:null };
    // start
    await p.click('#actions .btn');
    for (let i = 0; i < 8; i++) {
      const cur = await p.evaluate(() => window.__state.spotIdx);
      // click the active spot
      await p.evaluate((i) => {
        const s = window.__spots[i];
        document.getElementById('screen').dispatchEvent(new MouseEvent('click', {
          clientX: document.getElementById('screen').getBoundingClientRect().left + (s.x + s.w/2) * (document.getElementById('screen').getBoundingClientRect().width/480),
          clientY: document.getElementById('screen').getBoundingClientRect().top + (s.y + s.h/2) * (document.getElementById('screen').getBoundingClientRect().height/270),
          bubbles: true
        }));
      }, cur);
      await p.click('#actions .btn'); // openAct
      await p.click('#actions .btn'); // openEffect
      if (i === 7) {
        if (autoMerge) {
          // diverge: click a completed spot while seal gate open
          await p.evaluate(() => {
            const s = window.__spots[0];
            const cv = document.getElementById('screen');
            cv.dispatchEvent(new MouseEvent('click', {
              clientX: cv.getBoundingClientRect().left + (s.x + s.w/2) * (cv.getBoundingClientRect().width/480),
              clientY: cv.getBoundingClientRect().top + (s.y + s.h/2) * (cv.getBoundingClientRect().height/270),
              bubbles: true
            }));
          });
          r.diverge = {
            tag: await p.textContent('#dlgTag'),
            inpVisible: await p.isVisible('.merge input'),
            btnCount: await p.locator('#actions .btn').count()
          };
          // then merge correctly
          await p.fill('.merge input', '合入');
          await p.click('.merge .btn');
        }
      }
      // advance
      await p.click('#actions .btn');
      if (i === 6) {
        // after 7th advance, player walking to lab; spotIdx = 7, phase idle
        // click lab while walking
        await p.evaluate(() => {
          const s = window.__spots[7];
          const cv = document.getElementById('screen');
          cv.dispatchEvent(new MouseEvent('click', {
            clientX: cv.getBoundingClientRect().left + (s.x + s.w/2) * (cv.getBoundingClientRect().width/480),
            clientY: cv.getBoundingClientRect().top + (s.y + s.h/2) * (cv.getBoundingClientRect().height/270),
            bubbles: true
          }));
        });
        r.postAdvance = {
          tag: await p.textContent('#dlgTag'),
          phase: await p.evaluate(() => window.__state.phase)
        };
        // recover: click lab again (now phase='problem', ok)
        await p.evaluate(() => {
          const s = window.__spots[7];
          const cv = document.getElementById('screen');
          cv.dispatchEvent(new MouseEvent('click', {
            clientX: cv.getBoundingClientRect().left + (s.x + s.w/2) * (cv.getBoundingClientRect().width/480),
            clientY: cv.getBoundingClientRect().top + (s.y + s.h/2) * (cv.getBoundingClientRect().height/270),
            bubbles: true
          }));
        });
      }
    }
    r.errs = errs.slice();
    return r;
  }

  const out = await flow(true);
  console.log(JSON.stringify(out, null, 2));
  await b.close();
});
